using Order.Domain.Interfaces.Repositories;
using Order.Domain.Interfaces.Repositories.DataConnector;
namespace Order.Infra.Repositories { public class UnitOfWork : IUnitOfWork { private IClientRepository _clientRepository; private IProductRepository _productRepository; private IOrderRepository _orderRepository; private IUserRepository _userRepository; public UnitOfWork(IDbConnector dbConnector) { this.dbConnector = dbConnector ?? throw new ArgumentNullException(nameof(dbConnector)); } public IClientRepository ClientRepository => _clientRepository ??= new ClientRepository(dbConnector); public IOrderRepository OrderRepository => _orderRepository ??= new OrderRepository(dbConnector); public IProductRepository ProductRepository => _productRepository ??= new ProductRepository(dbConnector); public IUserRepository UserRepository => _userRepository ??= new UserRepository(dbConnector); public IDbConnector dbConnector { get; } public void BeginTransaction() => dbConnector.BeginTransaction(System.Data.IsolationLevel.ReadCommitted); public void CommitTransaction() => dbConnector.CommitTransaction(); public void RollbackTransaction() => dbConnector.RollbackTransaction(); } }